
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m05_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m05", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.051670831742397e-02, -7.041982459288157e-02, -7.027452769995922e-02, -7.004955183416188e-02, -6.968038365384384e-02, -6.901102864754020e-02, -6.759969445987891e-02, -6.403051740788766e-02, -5.364642487648175e-02, -2.565695647786408e-02, 1.330244553727306e-02, -3.893479906733691e-02, -4.524892819860563e-02, -2.570557199860498e-02, -7.463924943135455e-03, 1.932114794897271e-02, 2.539655535343456e-03, -1.666351843994306e-03, -1.935661663024385e-04, -5.900055623541021e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


